package com.retailcore.service;

import com.retailcore.dao.*;
import com.retailcore.entity.*;
import com.retailcore.orm.TransactionManager;

import java.sql.SQLException;
import java.util.Date;
import java.util.List;
import java.util.Map;

public class InventoryService {

    private static InventoryService instance;
    private final InventoryDAO inventoryDAO;
    private final ProductDAO productDAO;

    private InventoryService() {
        inventoryDAO = InventoryDAO.getInstance();
        productDAO = ProductDAO.getInstance();
    }

    public static synchronized InventoryService getInstance() {
        if (instance == null) {
            instance = new InventoryService();
        }
        return instance;
    }

    public void adjustInventory(int productId, int storeId, int newQuantity, int employeeId, String reason) throws SQLException {
        try {
            TransactionManager.begin();

            Inventory inv = inventoryDAO.findByProductAndStore(productId, storeId);
            if (inv == null) {
                throw new SQLException("Inventory record not found for product " + productId + " at store " + storeId);
            }

            int oldQuantity = inv.getQuantityOnHand();
            int difference = newQuantity - oldQuantity;

            inventoryDAO.adjustQuantity(productId, storeId, difference);

            AuditLogDAO.getInstance().logAction("tbl_Inventory", inv.getInventoryId(),
                    "ADJUST", "QuantityOnHand=" + oldQuantity, "QuantityOnHand=" + newQuantity, employeeId);

            TransactionManager.commit();
        } catch (SQLException e) {
            TransactionManager.rollback();
            throw e;
        }
    }

    public void receiveShipment(int purchaseOrderId, int employeeId) throws SQLException {
        try {
            TransactionManager.begin();

            PurchaseOrderDAO poDAO = PurchaseOrderDAO.getInstance();
            PurchaseOrder po = poDAO.findById(purchaseOrderId);
            if (po == null) {
                throw new SQLException("Purchase order not found: " + purchaseOrderId);
            }

            String sql = "SELECT * FROM [dbo].[tbl_PurchaseOrderItem] WHERE PurchaseOrderID = ?";
            List<Map<String, Object>> items = poDAO.executeQuery(sql, purchaseOrderId);

            for (Map<String, Object> item : items) {
                int productId = (int) item.get("ProductID");
                int qtyOrdered = (int) item.get("QuantityOrdered");

                Inventory inv = inventoryDAO.findByProductAndStore(productId, po.getStoreId());
                if (inv == null) {
                    Inventory newInv = new Inventory();
                    newInv.setProductId(productId);
                    newInv.setStoreId(po.getStoreId());
                    newInv.setQuantityOnHand(qtyOrdered);
                    inventoryDAO.insert(newInv);
                } else {
                    inventoryDAO.receiveStock(productId, po.getStoreId(), qtyOrdered);
                }
            }

            poDAO.receiveFullOrder(purchaseOrderId);

            TransactionManager.commit();
        } catch (SQLException e) {
            TransactionManager.rollback();
            throw e;
        }
    }

    public List<Inventory> getLowStockItems(int storeId) throws SQLException {
        return inventoryDAO.findLowStock(storeId);
    }

    public List<Inventory> getOutOfStockItems(int storeId) throws SQLException {
        return inventoryDAO.findOutOfStock(storeId);
    }

    public List<Map<String, Object>> getInventoryValuation(int storeId) throws SQLException {
        return inventoryDAO.getInventoryValueByStore(storeId);
    }

    public int getAvailableStock(int productId, int storeId) throws SQLException {
        return inventoryDAO.getAvailableQuantity(productId, storeId);
    }

    public int getTotalStockAcrossStores(int productId) throws SQLException {
        return inventoryDAO.getTotalQuantityAcrossStores(productId);
    }
}
package com.retailcore.orm;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class ConnectionPool {

    private static ConnectionPool instance;
    private BlockingQueue<Connection> availableConnections;
    private BlockingQueue<Connection> usedConnections;
    private String url;
    private String username;
    private String password;
    private int maxPoolSize;
    private int initialPoolSize;
    private AtomicInteger totalCreated;
    private long connectionTimeout;
    private long validationTimeout;
    private boolean autoCommit;
    private int transactionIsolation;

    private ConnectionPool() {
        totalCreated = new AtomicInteger(0);
        connectionTimeout = 30000;
        validationTimeout = 5000;
        autoCommit = true;
        transactionIsolation = Connection.TRANSACTION_READ_COMMITTED;
    }

    public static synchronized ConnectionPool getInstance() {
        if (instance == null) {
            instance = new ConnectionPool();
        }
        return instance;
    }

    public void initialize(String url, String username, String password, int initialSize, int maxSize) throws SQLException {
        this.url = url;
        this.username = username;
        this.password = password;
        this.initialPoolSize = initialSize;
        this.maxPoolSize = maxSize;
        this.availableConnections = new ArrayBlockingQueue<>(maxSize);
        this.usedConnections = new ArrayBlockingQueue<>(maxSize);

        try {
            Class.forName("com.microsoft.sqlserver.jdbc.SQLServerDriver");
        } catch (ClassNotFoundException e) {
            throw new SQLException("SQL Server JDBC driver not found", e);
        }

        for (int i = 0; i < initialSize; i++) {
            availableConnections.add(createConnection());
        }
    }

    private Connection createConnection() throws SQLException {
        Connection conn = DriverManager.getConnection(url, username, password);
        conn.setAutoCommit(autoCommit);
        conn.setTransactionIsolation(transactionIsolation);
        totalCreated.incrementAndGet();
        return conn;
    }

    public Connection getConnection() throws SQLException {
        Connection connection = null;
        try {
            connection = availableConnections.poll(connectionTimeout, TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new SQLException("Interrupted while waiting for connection", e);
        }

        if (connection == null) {
            if (totalCreated.get() < maxPoolSize) {
                connection = createConnection();
            } else {
                throw new SQLException("Connection pool exhausted. Max pool size: " + maxPoolSize);
            }
        }

        if (!isConnectionValid(connection)) {
            connection = createConnection();
        }

        usedConnections.add(connection);
        return connection;
    }

    public void releaseConnection(Connection connection) {
        if (connection != null) {
            usedConnections.remove(connection);
            try {
                if (!connection.isClosed()) {
                    if (!connection.getAutoCommit()) {
                        connection.rollback();
                        connection.setAutoCommit(autoCommit);
                    }
                    availableConnections.offer(connection);
                } else {
                    totalCreated.decrementAndGet();
                }
            } catch (SQLException e) {
                totalCreated.decrementAndGet();
            }
        }
    }

    private boolean isConnectionValid(Connection connection) {
        try {
            if (connection == null || connection.isClosed()) {
                return false;
            }
            return connection.isValid((int) (validationTimeout / 1000));
        } catch (SQLException e) {
            return false;
        }
    }

    public void shutdown() {
        for (Connection conn : usedConnections) {
            try {
                conn.close();
            } catch (SQLException ignored) {}
        }
        for (Connection conn : availableConnections) {
            try {
                conn.close();
            } catch (SQLException ignored) {}
        }
        availableConnections.clear();
        usedConnections.clear();
        totalCreated.set(0);
    }

    public int getAvailableCount() {
        return availableConnections.size();
    }

    public int getUsedCount() {
        return usedConnections.size();
    }

    public int getTotalCreated() {
        return totalCreated.get();
    }

    public void setConnectionTimeout(long timeout) {
        this.connectionTimeout = timeout;
    }

    public void setValidationTimeout(long timeout) {
        this.validationTimeout = timeout;
    }

    public void setAutoCommit(boolean autoCommit) {
        this.autoCommit = autoCommit;
    }

    public void setTransactionIsolation(int level) {
        this.transactionIsolation = level;
    }
}
package com.retailcore.orm;

import java.sql.Connection;
import java.sql.SQLException;
import java.sql.Savepoint;

public class TransactionManager {

    private static final ThreadLocal<Connection> transactionConnection = new ThreadLocal<>();
    private static final ThreadLocal<Integer> transactionDepth = new ThreadLocal<>();

    public static void begin() throws SQLException {
        Connection conn = transactionConnection.get();
        if (conn != null) {
            Integer depth = transactionDepth.get();
            transactionDepth.set(depth != null ? depth + 1 : 1);
            return;
        }

        conn = ConnectionPool.getInstance().getConnection();
        conn.setAutoCommit(false);
        transactionConnection.set(conn);
        transactionDepth.set(1);
    }

    public static void commit() throws SQLException {
        Integer depth = transactionDepth.get();
        if (depth == null || depth <= 0) {
            throw new SQLException("No active transaction to commit");
        }

        if (depth == 1) {
            Connection conn = transactionConnection.get();
            if (conn != null) {
                conn.commit();
                conn.setAutoCommit(true);
                ConnectionPool.getInstance().releaseConnection(conn);
                transactionConnection.remove();
            }
            transactionDepth.remove();
        } else {
            transactionDepth.set(depth - 1);
        }
    }

    public static void rollback() {
        Integer depth = transactionDepth.get();
        Connection conn = transactionConnection.get();

        if (conn != null) {
            try {
                conn.rollback();
                conn.setAutoCommit(true);
            } catch (SQLException ignored) {
            } finally {
                ConnectionPool.getInstance().releaseConnection(conn);
                transactionConnection.remove();
                transactionDepth.remove();
            }
        }
    }

    public static Savepoint setSavepoint(String name) throws SQLException {
        Connection conn = transactionConnection.get();
        if (conn == null) {
            throw new SQLException("No active transaction for savepoint");
        }
        return conn.setSavepoint(name);
    }

    public static void rollbackToSavepoint(Savepoint savepoint) throws SQLException {
        Connection conn = transactionConnection.get();
        if (conn == null) {
            throw new SQLException("No active transaction for rollback to savepoint");
        }
        conn.rollback(savepoint);
    }

    public static Connection getCurrentConnection() {
        return transactionConnection.get();
    }

    public static boolean isInTransaction() {
        return transactionConnection.get() != null;
    }

    public static Connection getConnectionForOperation() throws SQLException {
        Connection conn = transactionConnection.get();
        if (conn != null) {
            return conn;
        }
        return ConnectionPool.getInstance().getConnection();
    }

    public static void releaseConnectionIfNotInTransaction(Connection conn) {
        if (!isInTransaction() && conn != null) {
            ConnectionPool.getInstance().releaseConnection(conn);
        }
    }
}
